syntax:
template <typename T>
T myMax(T a, T b) {
    return (a > b) ? a : b;
}

example:
#include <iostream>
template <typename T>
void mySwap(T& a, T& b) { T t = a; a = b; b = t; }
int main() {
    int x = 1, y = 2; mySwap(x, y);
    std::cout << x << ' ' << y << '\n';
}

